"""Reference pieces: fixed requests, plans, and seeds (without LLM), generated by the symbolic engine and saved
side-by-side for composer comparison (listening, reading, descriptive metrics). Never a quality score.

    uv run python -m muschat.references baseline
"""

import json
import sys
from pathlib import Path
from types import SimpleNamespace

from muschat.composition import Composition
from muschat.export import metrics
from muschat.notation.lilypond import detect_lilypond, engrave, to_lilypond
from muschat.notation.musicxml import to_musicxml
from muschat.orchestrator import compose
from muschat.recipes import RECIPES
from muschat.score_ir import ScoreIR

REFERENCES_DIR = Path(".muschat") / "references"


def _op(procedure: str, **parameters: float) -> dict:
    return {"procedure": procedure, "parameters": [{"name": k, "value": v} for k, v in parameters.items()]}


PIECES: list[tuple[str, str, dict]] = [
    (
        "quarteto-espectral",
        "Eight measures for string quartet over the partials of C2, with sul ponticello and harmonics, crescendo.",
        {
            "instruments": ["violin", "violin", "viola", "cello"],
            "techniques": ["sul ponticello", "harmonic"],
            "operations": [
                _op("harmonic_series", fundamental=3600, partials=16, measures=8, microtone=1),
                _op("apply_techniques", ratio=0.3),
                _op("progressive_dynamics", start=2, end=7),
            ],
            "seed": 1,
        },
    ),
    (
        "flauta-clarone",
        "Harmonic series on 3600 mc for flute and bass clarinet, with flutter-tonguing, slap, jet whistle, and multiphonics.",
        {
            "instruments": ["flute", "bass clarinet"],
            "techniques": ["frullato", "slap", "jet whistle", "multiphonic"],
            "operations": [
                _op("harmonic_series", fundamental=3600, partials=16, measures=8, microtone=1),
                _op("apply_techniques", ratio=0.4),
            ],
            "seed": 2,
        },
    ),
    (
        "misto-adensando",
        "Eight measures for flute, clarinet, violin, and cello over the spectrum of G2, densifying from start to end, with pizzicato, staccato, and flutter-tonguing.",
        {
            "instruments": ["flute", "clarinet", "violin", "cello"],
            "techniques": ["pizzicato", "staccato", "frullato"],
            "operations": [
                _op("harmonic_series", fundamental=4300, partials=12, measures=8, microtone=1),
                _op("density", start=1, end=3),
                _op("apply_techniques", ratio=0.3),
            ],
            "seed": 3,
        },
    ),
    (
        "trio-subindo",
        "Eight measures for string trio over the partials of G1, rising in register and thinning out, with col legno battuto and sul tasto.",
        {
            "instruments": ["violin", "viola", "cello"],
            "techniques": ["col legno battuto", "sul tasto"],
            "operations": [
                _op("harmonic_series", fundamental=3100, partials=16, measures=8, microtone=1),
                _op("progressive_register", start=0, end=1200),
                _op("density", start=2, end=0.5),
                _op("apply_techniques", ratio=0.3),
            ],
            "seed": 4,
        },
    ),
]

CHECKLIST = """\
- [ ] Transposed parts are correct (each performer reads their part)
- [ ] Nothing unplayable (register, technique, duration)
- [ ] Identifiable phrases (beginning, arrival, breathing)
- [ ] Justified leaps (no isolated octave jumps without reason)
- [ ] Technique placed where it speaks (in the register and gesture where it works)
- Listening (1 to 5, comment):
- Reading (1 to 5, comment):
"""


class _FixedPlanGenerator:
    def __init__(self, plan: dict):
        self.text = json.dumps(plan)

    def generate_content(self, *, model, contents, config):
        return SimpleNamespace(text=self.text)


class _EmptyChat:
    def get_history(self):
        return []

    def send_message(self, message, config=None):
        return SimpleNamespace(text="")


def run_fixed_plan(request: str, raw_plan: dict, composition: Composition) -> ScoreIR:
    """Execute a deterministic Python-only plan via `compose` without calling an external LLM."""
    result = compose(
        request,
        composition,
        generator=_FixedPlanGenerator({"goal": request, **raw_plan}),
        chat=_EmptyChat(),
        model="fixed-reference",
    )
    if result.version is None:
        raise RuntimeError(result.summary)
    return result.version.ir


def generate_references(label: str, *, root: Path = REFERENCES_DIR, lilypond=None) -> Path:
    """Generate all reference pieces under `root/label`."""
    directory = root / label
    directory.mkdir(parents=True, exist_ok=True)
    all_metrics: dict[str, dict] = {}
    checklist = [f"# Reading Checklist: {label}\n"]
    for name, request, plan_dict in PIECES:
        comp = Composition()
        ir = run_fixed_plan(request, plan_dict, comp)
        (directory / f"{name}.musicxml").write_text(to_musicxml(ir), encoding="utf-8")
        (directory / f"{name}.json").write_text(comp.to_json(), encoding="utf-8")
        for key, pdf in engrave(to_lilypond(ir), lilypond).pdfs.items():
            (directory / f"{name}-{key}.pdf").write_bytes(pdf)
        all_metrics[name] = {
            "request": request,
            "summary": comp.current.summary if comp.current else "",
            **metrics(ir),
        }
        checklist.append(f"## {name}\n\n{request}\n\n{CHECKLIST}")
    (directory / "metrics.json").write_text(json.dumps(all_metrics, ensure_ascii=False, indent=2), encoding="utf-8")
    (directory / "checklist.md").write_text("\n".join(checklist), encoding="utf-8")
    return directory


def generate_recipe_references(label: str, *, root: Path = REFERENCES_DIR, lilypond=None) -> Path:
    """Apply every recipe in `RECIPES` to each reference piece and save before/after metrics and scores."""
    directory = root / label
    directory.mkdir(parents=True, exist_ok=True)
    all_metrics: dict[str, dict] = {}
    checklist = [f"# Recipes: {label}\n"]
    for name, request, plan_dict in PIECES:
        base = Composition()
        original = run_fixed_plan(request, plan_dict, base)
        for recipe_name, recipe in RECIPES.items():
            comp = Composition()
            comp.add(original, "original reference", {}, previous=None)
            transform = {
                "goal": recipe_name,
                "recipe": recipe_name,
                "recipe_rationale": "comparison with reference",
                "seed": plan_dict["seed"],
                "operations": [_op(op, **params) for op, params in recipe.chain],
            }
            ir = run_fixed_plan(recipe_name, transform, comp)
            key = f"{name}-{recipe_name}"
            (directory / f"{key}.musicxml").write_text(to_musicxml(ir), encoding="utf-8")
            (directory / f"{key}.json").write_text(comp.to_json(), encoding="utf-8")
            sources = to_lilypond(ir)
            (directory / f"{key}.ly").write_text(sources["score"], encoding="utf-8")
            if lilypond:
                engraved = engrave({"score": sources["score"]}, lilypond)
                if engraved.warning:
                    raise RuntimeError(f"{key}: {engraved.warning}")
                (directory / f"{key}.pdf").write_bytes(engraved.pdfs["score"])
            all_metrics[key] = {"before": metrics(original), "after": metrics(ir)}
            checklist.append(f"## {key}\n\n{CHECKLIST}")
    (directory / "metrics.json").write_text(json.dumps(all_metrics, ensure_ascii=False, indent=2), encoding="utf-8")
    (directory / "checklist.md").write_text("\n".join(checklist), encoding="utf-8")
    return directory


if __name__ == "__main__":
    if len(sys.argv) not in (2, 3) or (len(sys.argv) == 3 and sys.argv[2] != "--recipes"):
        sys.exit("usage: uv run python -m muschat.references <label> [--recipes]")
    runner = generate_recipe_references if len(sys.argv) == 3 else generate_references
    print(runner(sys.argv[1], lilypond=detect_lilypond()).resolve())
